<?php
$current=[];foreach($records as $record){$key=$record['values']['code']??'DEFAULT';if(!isset($current[$key]))$current[$key]=$record;}
$isComponent=$module==='pay_component';$listTitle=$isComponent?'Allowances & deductions':($module==='pay_structure'?'Salary structures':'Payslip designs');
?>
<section class="card pay-panel" data-pay-list>
<div class="pay-panel-heading"><div><h2><?=h($listTitle)?> <span class="pay-count"><?=count($current)?></span></h2><p class="pay-muted">Latest revision of each configuration. Earlier revisions remain in history.</p></div><label class="pay-search">Search<input type="search" data-pay-search placeholder="Search by name or code" aria-label="Search payroll configurations"></label></div>
<div class="pay-filter-chips" aria-label="Configuration filters"><button type="button" class="button is-active" data-pay-filter="" aria-pressed="true">All <span><?=count($current)?></span></button><?php if($isComponent):foreach(['Earning'=>'Allowances','Deduction'=>'Deductions','Employer'=>'Employer contributions'] as $category=>$label):$count=count(array_filter($current,fn($r)=>$r['values']['category']===$category));?><button type="button" class="button" data-pay-filter="<?=h($category)?>" aria-pressed="false"><?=h($label)?> <span><?=$count?></span></button><?php endforeach;endif;?></div>
<div class="pay-table pay-modern-table"><table><thead><tr><th>Name / code</th><?php if($isComponent):?><th>Type</th><th>Calculation</th><th>Amount / rate</th><th>Based on</th><th>Prorated</th><?php elseif($module==='pay_structure'):?><th>Components</th><th>Variable pay</th><?php else:?><th>Layout</th><th>Custom attributes</th><?php endif;?><th>Effective period</th><th>Status</th><th>Actions</th></tr></thead><tbody>
<?php foreach($current as $r):$d=$r['values'];?><tr data-pay-row data-pay-category="<?=h($d['category']??'')?>"><td><strong><?=h($r['title'])?></strong><small><?=h($d['code']??'DEFAULT')?></small></td><?php if($isComponent):?><td><?=h($d['category']==='Earning'?'Allowance':$d['category'])?></td><td><?=h($d['calculation'])?></td><td><?=h(in_array($d['calculation'],['Fixed','Percentage'],true)?(($d['value']??'0').($d['calculation']==='Percentage'?'%':'')):($d['calculation']==='Formula'?($d['formula']??''):'Calculated'))?></td><td><?=h($d['basis']??'—')?></td><td><?=!empty($d['proratable'])?'Yes':'No'?></td><?php elseif($module==='pay_structure'):?><td><?=count($d['components']??[])?> components<details><summary>View components</summary><?php foreach($d['components']??[] as $component):?><p><?=h(($component['name']??$component['code']).' · '.$component['category'])?></p><?php endforeach;?></details></td><td><?=!empty($d['variable_enabled'])?'Up to '.h((string)($d['variable_cap']??0)).'%':'Disabled'?></td><?php else:?><td><?=($d['template_mode']??'standard')==='html'?'Custom HTML':'Standard'?></td><td><?=count($d['attributes']??[])?></td><?php endif;?><td><?=h($d['effective_from'])?><small><?=h($d['effective_to']?:'No end date')?></small></td><td><span class="pay-badge <?=$r['status']==='Active'?'pay-badge-success':''?>"><?=h($r['status'])?></span></td><td><?php if(can($pdo,$user,'payroll.settings.manage')):?><a class="button" href="?page=<?=h($page)?>&revision=<?=$r['id']?>">Revise</a><?php else:?>View only<?php endif;?></td></tr><?php endforeach;?>
<tr data-pay-empty <?=count($current)?'hidden':''?>><td colspan="9">No matching configurations.</td></tr></tbody></table></div>
<p class="pay-muted" data-pay-result><?=count($current)?> configurations</p></section>
